package com.gazellio.platform.controller; import com.gazellio.platform.dto.ApiDtos.AuditView; import com.gazellio.platform.repository.AuditEventRepository; import com.gazellio.platform.service.ViewService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/audit") @RequiredArgsConstructor public class AuditController {private final AuditEventRepository repo;private final ViewService view;@GetMapping public List<AuditView> recent(){return repo.findTop100ByOrderByCreatedAtDesc().stream().map(view::audit).toList();}}
